
'use strict';
const STORAGE_KEY='trfc-ministry-uniforms-v2';
const LEGACY_KEY='protocol-uniform-scheduler-v1';
const CATEGORIES={suits:'Suits',shirts:'Shirts',ties:'Ties'};
const WEEKDAYS={0:'Sunday',5:'Friday'};
const monthFmt=new Intl.DateTimeFormat('en-ZA',{month:'long',year:'numeric',timeZone:'UTC'});
const dateFmt=new Intl.DateTimeFormat('en-ZA',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});
const originalColors={
 suits:[{id:'s-black',name:'Black',hex:'#191b1e',confirmed:true},{id:'s-navy',name:'Navy Blue',hex:'#1e385b',confirmed:true},{id:'s-light',name:'Light Blue',hex:'#9bc8eb',confirmed:true},{id:'s-charcoal',name:'Charcoal Grey',hex:'#4c5259',confirmed:true}],
 shirts:[{id:'h-white',name:'White',hex:'#fafafa',confirmed:true},{id:'h-black',name:'Black',hex:'#191b1e',confirmed:true},{id:'h-light',name:'Light Blue',hex:'#b2d6f1',confirmed:true},{id:'h-peach',name:'Peach',hex:'#eab6a1',confirmed:true}],
 ties:[{id:'t-black',name:'Black',hex:'#191b1e',confirmed:true},{id:'t-maroon',name:'Maroon',hex:'#772d47',confirmed:true},{id:'t-navy',name:'Navy Blue',hex:'#1e385b',confirmed:true},{id:'t-red',name:'Plain Red',hex:'#bd3037',confirmed:true},{id:'t-blackwhite',name:'Black with White Print',hex:'#343638',confirmed:false},{id:'t-peachnavy',name:'Peach & Navy Print',hex:'#d7a698',confirmed:false}]
};
// Explicit, editable allowlist: no unreviewed Cartesian-product pairings.
const starterTriples=[
 ['s-black','h-white','t-black'],['s-black','h-white','t-maroon'],['s-black','h-white','t-navy'],['s-black','h-white','t-red'],
 ['s-black','h-light','t-black'],['s-black','h-light','t-maroon'],['s-black','h-light','t-navy'],
 ['s-black','h-black','t-black'],
 ['s-navy','h-white','t-navy'],['s-navy','h-white','t-maroon'],['s-navy','h-white','t-red'],
 ['s-navy','h-light','t-navy'],['s-navy','h-light','t-maroon'],['s-navy','h-peach','t-navy'],
 ['s-charcoal','h-white','t-black'],['s-charcoal','h-white','t-maroon'],['s-charcoal','h-white','t-navy'],['s-charcoal','h-white','t-red'],
 ['s-charcoal','h-light','t-black'],['s-charcoal','h-light','t-maroon'],['s-charcoal','h-light','t-navy'],['s-charcoal','h-peach','t-navy'],
 ['s-light','h-white','t-navy'],['s-light','h-white','t-maroon'],['s-light','h-white','t-black']
];
function initialState(){
 const now=new Date(), firstNext=new Date(now.getFullYear(),now.getMonth()+1,1);
 const startMonth=firstNext.getFullYear()+'-'+String(firstNext.getMonth()+1).padStart(2,'0');
 const outfits=starterTriples.map((trip,i)=>({id:'c-'+(i+1),suitId:trip[0],shirtId:trip[1],tieId:trip[2],specialOnly:trip[0]==='s-black'&&trip[1]==='h-black'&&trip[2]==='t-black'}));
 return {labels:{suits:'Suits',shirts:'Shirts',ties:'Ties'},palette:JSON.parse(JSON.stringify(originalColors)),outfits,rules:[{id:'r-last',name:'All-black month end',kind:'last',weekday:0,date:'',outfitId:'c-8'}],settings:{startMonth,months:3,includeFridays:false}};
}
function blankState(){const d=initialState();return {...d,labels:{suits:'Main garment',shirts:'Second garment',ties:'Accessory'},palette:{suits:[],shirts:[],ties:[]},outfits:[],rules:[]}}
function newWorkspace(){let imported=null;try{const old=localStorage.getItem(LEGACY_KEY);if(old)imported=validateImport(JSON.parse(old))}catch(e){}return {active:'protocol',teams:{protocol:{name:'Protocol',data:imported||initialState()},choir:{name:'Choir',data:blankState()},ushers:{name:'Ushers',data:blankState()},hospitality:{name:'Hospitality',data:blankState()}},appearance:{primary:'#233a35',accent:'#cba968',logo:''}}}
function loadWorkspace(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return newWorkspace();const ws=JSON.parse(raw);if(!ws||!ws.teams||!Object.keys(ws.teams).length)throw Error('Bad workspace');for(const team of Object.values(ws.teams)){team.name=cleanText(team.name,60);team.data=validateImport(team.data)}if(!ws.teams[ws.active])ws.active=Object.keys(ws.teams)[0];ws.appearance ||= {primary:'#233a35',accent:'#cba968',logo:''};return ws}catch(e){return newWorkspace()}}
let workspace={active:null,teams:{},appearance:{primary:'#333434',accent:'#c49a37',logo:''}},state=blankState(),tab='schedule';
let currentUser=null,csrf='',saveQueues={},syncErrors={},onlineStatus='idle',previewCache={},previewErrors={};
const api=async(path,options={})=>{const req={credentials:'same-origin',...options,headers:{'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(['POST','PUT','DELETE','PATCH'].includes(options.method)?{'X-CSRF-Token':csrf}:{}),...(options.headers||{})}};const r=await fetch('/api'+path,req);const o=await r.json().catch(()=>({}));if(!r.ok)throw Error(typeof o.detail==='string'?o.detail:'Request failed ('+r.status+')');return o};
const payload=obj=>JSON.stringify(obj);
function notify(message,problem=false){const el=document.getElementById('notification');el.textContent=message;el.style.background=problem?'#8b3831':'#262727';el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),5200)}
function setCloudStatus(status){onlineStatus=status;const el=document.getElementById('cloudState');if(el){el.innerHTML=`<span class="status-dot ${status==='Saving…'?'pending':status==='Sync failed'?'error':''}"></span> ${esc(status)}`}}
async function bootstrap(){document.getElementById('pageLoader').classList.add('hide');try{const u=await api('/me');await enter(u)}catch{showAuth()}}
function showAuth(){document.getElementById('appShell').classList.add('hide');document.getElementById('authScreen').classList.remove('hide');logoFallback();api('/bootstrap-status').then(r=>{document.getElementById('setupForm').classList.toggle('hide',!r.setup_required);document.getElementById('loginForm').classList.toggle('hide',r.setup_required);document.getElementById('authSwitch').classList.toggle('hide',r.setup_required);document.getElementById('registerForm').classList.add('hide');if(!r.setup_required)loadDepartments();document.getElementById('authModeTitle').textContent=r.setup_required?'Set up your workspace':'Welcome back';document.getElementById('authIntro').textContent=r.setup_required?'Create the first administrator account. Your private setup key is configured on the server.':'Sign in to manage your ministry uniforms and publish schedules.';if(r.setup_required&&!r.ready)document.getElementById('authError').textContent='The server needs a SETUP_KEY environment variable before initial setup.';}).catch(e=>{document.getElementById('authError').textContent=e.message})}
async function enter(u){currentUser=u;csrf=u.csrf;document.body.classList.toggle('member-mode',u.role!=='admin');const teams=await api('/teams');workspace.teams={};for(const t of teams){workspace.teams[t.id]={name:t.name,slug:t.slug,id:t.id,version:t.version,published_at:t.published_at,data:null}}workspace.active=String(teams[0]?.id||'');const appearance=await api('/branding');workspace.appearance=appearance;document.getElementById('authScreen').classList.add('hide');document.getElementById('appShell').classList.remove('hide');document.getElementById('currentUser').textContent=u.email;logoFallback();document.getElementById('adminButtons').classList.toggle('hide',u.role!=='admin');document.getElementById('tabs').parentElement.classList.toggle('hide',u.role!=='admin');document.querySelector('.team-switch').classList.toggle('hide',u.role!=='admin');document.querySelectorAll('[data-action=addTeam],[data-action=removeTeam],[data-action=branding],[data-action=exportWorkspace]').forEach(b=>b.classList.toggle('hide',u.role!=='admin'));
if(u.role==='admin'){if(teams.length)await selectTeam(String(teams[0].id));else{state=blankState();render()}}else{await renderMemberDashboard()}setCloudStatus('Connected');if(u.must_change)notify('Your administrator issued a temporary password. Change it from the Account menu.',true)}
async function selectTeam(id){if(!workspace.teams[id])return;setCloudStatus('Loading…');if(!workspace.teams[id].data){const t=await api('/teams/'+id);workspace.teams[id].data=t.config;workspace.teams[id].version=t.version;workspace.teams[id].published_at=t.published_at;}workspace.active=id;state=workspace.teams[id].data;tab='schedule';render();setCloudStatus('Connected');await refreshPreview(id)}
async function refreshPreview(id){try{const value=await api('/teams/'+id+'/preview');if(workspace.teams[id]?.version!==value.version)return;delete previewErrors[id];previewCache[id]=value.rows.map(r=>({date:r.date,day:Number(r.date.slice(-2)),weekday:r.weekday,month:r.date.slice(0,7),outfit:r.outfit?workspace.teams[id].data.outfits.find(o=>o.id===r.outfit.id)||null:null,rule:r.rule?{name:r.rule}:null}));if(workspace.active===id&&tab==='schedule')render()}catch(e){previewErrors[id]=e.message;previewCache[id]=null;if(workspace.active===id&&tab==='schedule')render();notify('Schedule preview unavailable: '+e.message,true)}}
async function saveTeam(id,data){const t=workspace.teams[id];if(!t)return;const oldVersion=t.version;const response=await api('/teams/'+id+'/config',{method:'PUT',body:payload({version:oldVersion,config:data})});t.version=response.version;return response}
function logoFallback(){document.querySelectorAll('#brandIcon img,.auth-logo').forEach(img=>{img.addEventListener('error',()=>{if(img.classList.contains('auth-logo')){img.outerHTML='<div class="auth-logo brand-fallback" aria-label="TRFC">TRFC</div>'}else{img.closest('#brandIcon').textContent='TRFC'}})})}
function save(){if(currentUser?.role!=='admin')return;if(!workspace.active)return;const id=workspace.active;workspace.teams[id].data=state;const data=JSON.parse(JSON.stringify(state));previewCache[id]=null;setCloudStatus('Saving…');saveQueues[id]=(saveQueues[id]||Promise.resolve()).catch(()=>{}).then(()=>saveTeam(id,data)).then(()=>{delete syncErrors[id];setCloudStatus('Saved to cloud');if(workspace.active===id)refreshPreview(id)}).catch(async err=>{syncErrors[id]=err.message;setCloudStatus('Sync failed');notify(err.message,true);if(err.message.includes('edited elsewhere')){workspace.teams[id].data=null;await selectTeam(id).catch(()=>{})}});renderStats()}

function activeName(){return workspace.teams[workspace.active]?.name||'Ministry'}
function renderTeams(){const sel=document.getElementById('teamSelect');sel.innerHTML=Object.entries(workspace.teams).map(([id,t])=>`<option value="${esc(id)}" ${id===workspace.active?'selected':''}>${esc(t.name)}</option>`).join('');document.documentElement.style.setProperty('--green',workspace.appearance.primary);document.documentElement.style.setProperty('--green-dark',workspace.appearance.primary);document.documentElement.style.setProperty('--gold',workspace.appearance.accent);document.querySelector('.masthead').style.background=workspace.appearance.primary;document.querySelector('.brand-mark').style.background=workspace.appearance.accent;const logo=workspace.appearance.logo;document.getElementById('brandIcon').innerHTML=logo&&(/^(data:image\/(png|jpeg|webp);base64,)/.test(logo)||logo==='https://prophetdaviduche.net/img/Logo.png')?`<img src="${logo}" alt="TRFC emblem" style="width:100%;height:100%;object-fit:contain">`:'TRFC'}


function cleanText(t,n=70){return String(t??'').trim().slice(0,n)}
function validateImport(v){
 if(!v||typeof v!=='object'||!v.palette||!Array.isArray(v.outfits)||!Array.isArray(v.rules))throw Error('Not a valid uniform configuration file.');
 const palette={};
 for(const cat of Object.keys(CATEGORIES)){
  if(!Array.isArray(v.palette[cat]))throw Error('Missing '+cat+' list.');
  palette[cat]=v.palette[cat].slice(0,100).map(x=>({id:cleanText(x.id,120),name:cleanText(x.name,50),hex:/^#[0-9a-f]{6}$/i.test(x.hex)?x.hex:'#777777',confirmed:x.confirmed!==false})).filter(x=>x.id&&x.name);
 }
 const outfits=v.outfits.slice(0,3000).map(x=>({id:cleanText(x.id,120),suitId:cleanText(x.suitId,120),shirtId:cleanText(x.shirtId,120),tieId:cleanText(x.tieId,120),specialOnly:!!x.specialOnly})).filter(x=>x.id);
 const rules=v.rules.slice(0,300).map(x=>({id:cleanText(x.id,120),name:cleanText(x.name,70),kind:['last','first','second','third','fourth','date'].includes(x.kind)?x.kind:'last',weekday:Number(x.weekday)===5?5:0,date:/^\d{4}-\d{2}-\d{2}$/.test(x.date)?x.date:'',outfitId:cleanText(x.outfitId,120)})).filter(x=>x.id&&x.outfitId&&(x.kind!=='date'||(x.date&&dateKey(parseISODate(x.date))===x.date&&[0,5].includes(parseISODate(x.date).getUTCDay()))));
 const s=v.settings||{};
 const settings={startMonth:/^\d{4}-(0[1-9]|1[012])$/.test(s.startMonth)?s.startMonth:'2026-11',months:[1,2,3,4,6,12].includes(Number(s.months))?Number(s.months):3,includeFridays:!!s.includeFridays};
 return{palette,outfits,rules,settings,labels:Object.fromEntries(Object.keys(CATEGORIES).map(k=>[k,cleanText(v.labels?.[k]||CATEGORIES[k],40)]))};
}
function uid(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function item(cat,id){return state.palette[cat].find(i=>i.id===id)}
function isUsable(outfit){return !!outfit&&[['suits','suitId'],['shirts','shirtId'],['ties','tieId']].every(([cat,key])=>item(cat,outfit[key])?.confirmed)}
function validOutfits(){return state.outfits.filter(isUsable)}
function swatch(entry){return `<span class="swatch" style="background:${esc(entry?.hex||'#d8ded9')}" aria-hidden="true"></span>`}
function garment(entry,role){return `<span class="garment">${swatch(entry)}<span>${esc(entry?.name||'Missing '+role)}</span></span>`}
function outfitPreview(o){return o?`<div class="outfit">${garment(item('suits',o.suitId),'suit')}${garment(item('shirts',o.shirtId),'shirt')}${garment(item('ties',o.tieId),'tie')}</div>`:'<span class="empty-uniform">No approved outfit available</span>'}
function renderStats(){const el=document.getElementById('heroStats');if(el)el.innerHTML=`<div class="hero-stat"><strong>${state.palette.suits.length+state.palette.shirts.length+state.palette.ties.length}</strong><span>Uniform colours</span></div><div class="hero-stat"><strong>${validOutfits().length}</strong><span>Approved outfits</span></div><div class="hero-stat"><strong>${state.rules.length}</strong><span>Special rules</span></div>`}
function render(){if(currentUser?.role!=='admin')return;if(!workspace.active)return;Object.assign(CATEGORIES,state.labels||{});renderTeams();renderStats();for(const b of document.querySelectorAll('.tab'))b.classList.toggle('active',b.dataset.tab===tab);document.getElementById('main').innerHTML=tab==='schedule'?renderSchedule():tab==='uniforms'?renderUniforms():tab==='rules'?renderRules():renderAttendance()}
function parseISODate(iso){const [y,m,d]=iso.split('-').map(Number);return new Date(Date.UTC(y,m-1,d))}
function dateKey(d){return d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0')+'-'+String(d.getUTCDate()).padStart(2,'0')}
function monthKey(d){return dateKey(d).slice(0,7)}
function dateSequence(){const [y,m]=state.settings.startMonth.split('-').map(Number),out=[];
 for(let n=0;n<state.settings.months;n++){
  const first=new Date(Date.UTC(y,m-1+n,1)),yr=first.getUTCFullYear(),mo=first.getUTCMonth(),days=new Date(Date.UTC(yr,mo+1,0)).getUTCDate();
  for(let day=1;day<=days;day++){const d=new Date(Date.UTC(yr,mo,day)),w=d.getUTCDay();if(w===0||(w===5&&state.settings.includeFridays))out.push(d)}
 }
 return out;
}
function ruleMatches(r,d){if(r.kind==='date')return r.date===dateKey(d);
 if(r.weekday!==d.getUTCDay())return false;
 const day=d.getUTCDate();if(r.kind==='last')return new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),day+7)).getUTCMonth()!==d.getUTCMonth();
 return {first:1,second:2,third:3,fourth:4}[r.kind]===Math.ceil(day/7);
}
function activeRule(d){return [...state.rules].reverse().filter(r=>ruleMatches(r,d)&&isUsable(state.outfits.find(o=>o.id===r.outfitId))).sort((a,b)=>Number(b.kind==='date')-Number(a.kind==='date'))[0]||null}
function hashString(s){let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return h>>>0}
function chooseOutfit(d,history,available){
 if(!available.length)return null;
 const currentMonth=monthKey(d),prev=history.at(-1),two=history.at(-2),weekly=[...history].reverse().find(h=>h.weekday===d.getUTCDay());
 function count(type,val,sameMonth=false){return history.filter(h=>(!sameMonth||h.month===currentMonth)&&h.outfit&&h.outfit[type]===val).length}
 let best=null,bestScore=Infinity;
 for(const o of available){let score=0;
  if(prev?.outfit){if(prev.outfit.id===o.id)score+=1000;if(prev.outfit.suitId===o.suitId)score+=32;if(prev.outfit.shirtId===o.shirtId)score+=5;if(prev.outfit.tieId===o.tieId)score+=3}
  if(two?.outfit?.id===o.id)score+=75;
  if(weekly?.outfit?.id===o.id)score+=90;
  if(weekly?.outfit?.suitId===o.suitId)score+=16;
  score+=count('suitId',o.suitId,true)*20+count('shirtId',o.shirtId,true)*3+count('tieId',o.tieId,true)*1.5;
  score+=count('suitId',o.suitId)*4+count('id',o.id)*6+count('shirtId',o.shirtId)*1.5;
  score+=(hashString(dateKey(d)+o.id)%997)/997;
  if(score<bestScore){bestScore=score;best=o}
 }
 return best;
}
function generate(){const history=[],available=validOutfits().filter(o=>!o.specialOnly);return dateSequence().map(d=>{
 const rule=activeRule(d);const outfit=rule?state.outfits.find(o=>o.id===rule.outfitId):chooseOutfit(d,history,available);
 const row={date:dateKey(d),day:d.getUTCDate(),weekday:d.getUTCDay(),month:monthKey(d),outfit:outfit||null,rule};history.push(row);return row;
})}
function renderSchedule(){const schedule=previewCache[workspace.active]||[],months=[...new Set(schedule.map(r=>r.month))];let warnings=previewErrors[workspace.active]?`<div class="notice warning" role="alert">${esc(previewErrors[workspace.active])}</div>`:!previewCache[workspace.active]?'<div class="notice">Loading the server schedule preview.</div>':'';
 if(!validOutfits().some(o=>!o.specialOnly))warnings+='<div class="notice warning">You need at least one approved outfit that is available for normal rotation. Visit <strong>Uniforms &amp; outfits</strong> to add one.</div>';
 const ignored=state.rules.filter(r=>!isUsable(state.outfits.find(o=>o.id===r.outfitId)));
 if(ignored.length)warnings+=`<div class="notice warning">${ignored.length} rule(s) refer to an unavailable outfit. Confirm the colours or change the rules before publishing.</div>`;
 const upcoming=months.map(m=>{const rows=schedule.filter(r=>r.month===m);return `<section class="month"><div class="month-head"><h3>${esc(monthFmt.format(parseISODate(m+'-01')))}</h3><small>${rows.length} services</small></div>${rows.map(row=>`<div class="date-row"><div class="date-chip ${row.weekday===5?'friday':''}"><span class="weekday">${WEEKDAYS[row.weekday]}</span><span class="day">${row.day}</span></div><div>${outfitPreview(row.outfit)}<div class="outfit-meta">${row.rule?`<span class="tag special">★ ${esc(row.rule.name)}</span>`:row.outfit?'<span class="tag">Scheduled rotation</span>':'<span class="tag muted">Unassigned</span>'}${row.outfit?.specialOnly?'<span class="tag muted">Special-only outfit</span>':''}</div></div></div>`).join('')}</section>`}).join('');
 return `<section class="panel"><div class="pub-card no-print"><div><span class="slabel">Publication</span><strong>${workspace.teams[workspace.active]?.published_at?'Published for department members':'Admin-only draft'}</strong><p>${workspace.teams[workspace.active]?.published_at?'Signed-in members of this department can view the last published snapshot. Edits remain private until you publish again.':'Only administrators can see this draft. Publish it once all outfits are approved.'}</p></div><div class="hstack"><button class="button primary" data-action="publish">Publish schedule</button>${workspace.teams[workspace.active]?.published_at?'<button class="button" data-action="publicLink">Copy department link</button><button class="button danger" data-action="unpublish">Unpublish</button>':''}</div></div><div class="section-head"><div><h2>Upcoming uniform schedule</h2><p>Automatically rotates through combinations you approve. Special rules take priority over normal rotation.</p></div><div class="hstack no-print"><button class="button" data-action="copySchedule">Copy for WhatsApp</button><button class="button" data-action="exportCsv">Export CSV</button><button class="button primary" data-action="print">Print / Save PDF</button></div></div><div class="controls no-print"><div class="field"><label for="startMonth">Starting month</label><input id="startMonth" type="month" value="${esc(state.settings.startMonth)}" min="2000-01" max="2100-12"></div><div class="field"><label for="monthCount">Plan ahead</label><select id="monthCount">${[1,2,3,4,6,12].map(n=>`<option value="${n}" ${state.settings.months===n?'selected':''}>${n} month${n===1?'':'s'}</option>`).join('')}</select></div><label class="switchline"><input type="checkbox" id="includeFridays" ${state.settings.includeFridays?'checked':''}> Include Fridays</label><div class="controls-note">Schedules are generated automatically when you change these settings. Every Friday/Sunday uses a fully approved outfit.</div></div><div class="info-row"><span class="pill">✓ ${schedule.length} services planned</span><span class="pill">◌ ${validOutfits().filter(o=>!o.specialOnly).length} rotating options</span><span class="pill special">★ ${schedule.filter(x=>x.rule).length} special-rule dates</span></div>${warnings}<div class="month-list">${upcoming}</div><div class="notice no-print">All-black month end is enabled as an <strong>example default rule</strong>. You can edit your dress code by removing that rule, adding other rules or changing the approved outfits.</div></section>`;
}
function renderUniforms(){return `<div class="section-head"><div><h2>Uniform colours &amp; approved combinations</h2><p>For Protocol, starter colours come from your supplied list. Other ministries start blank. Only combinations explicitly approved below can be scheduled.</p></div><div class="hstack"><button class="button" data-action="exportJson">Back up settings</button><button class="button" data-action="importJson">Import settings</button></div></div><form id="labelsForm" class="label-grid panel">${Object.entries(CATEGORIES).map(([k,v])=>`<div class="field"><label>${{suits:'Layer 1',shirts:'Layer 2',ties:'Layer 3'}[k]} label</label><input name="${k}" value="${esc(state.labels?.[k]||v)}" maxlength="40"></div>`).join('')}<button type="submit" class="button primary full">Save garment labels</button></form><div class="three-col">${Object.entries(CATEGORIES).map(([key,title])=>`<section class="panel palette-panel"><h3>${title} <span class="caption">(${state.palette[key].length})</span></h3><div class="palette-list">${state.palette[key].map(c=>`<div class="color-item ${!c.confirmed?'pending':''}" title="${!c.confirmed?'Pending confirmation before purchasing':''}">${swatch(c)} <span class="color-name">${esc(c.name)}</span> ${key==='ties'&&!c.confirmed?`<button class="button small" data-action="confirmTie" data-id="${esc(c.id)}" title="Mark this tie as confirmed">Confirm</button>`:''}${key==='ties'&&c.confirmed&&['t-blackwhite','t-peachnavy'].includes(c.id)?`<button class="x" title="Mark as awaiting confirmation" data-action="unconfirmTie" data-id="${esc(c.id)}">↩</button>`:''}<button class="x" title="Remove ${esc(c.name)}" data-action="removeColor" data-kind="${key}" data-id="${esc(c.id)}">×</button></div>`).join('')||'<span class="caption">None added</span>'}</div><form class="color-form add-color-form" data-kind="${key}"><div class="field grow"><label>New colour</label><input name="colorName" required placeholder="e.g. Burgundy" maxlength="50" aria-label="New ${title.toLowerCase()} colour"></div><div class="field"><label>Swatch</label><input name="hex" type="color" value="#516b82" aria-label="Colour swatch"></div><button class="button small primary" type="submit">Add</button></form>${key==='ties'?'<p class="mini-rule">Printed ties marked “confirm” are excluded until you explicitly approve them.</p>':''}</section>`).join('')}</div><div class="builder-grid"><section class="panel outfit-builder"><h3 class="subhead">Approve a new outfit</h3><p class="caption">Choose a cohesive suit, shirt and tie. Adding a colour does not automatically approve every pairing.</p><form class="form-grid" id="outfitForm"><div class="field full"><label for="outfitSuit">Suit</label><select id="outfitSuit" name="suit" required>${optionsFor('suits')}</select></div><div class="field"><label for="outfitShirt">Shirt</label><select id="outfitShirt" name="shirt" required>${optionsFor('shirts')}</select></div><div class="field"><label for="outfitTie">Tie</label><select id="outfitTie" name="tie" required>${optionsFor('ties',true)}</select></div><label class="switchline full"><input type="checkbox" name="specialOnly"> Only use for special rules</label><button class="button primary full" type="submit">Add approved combination</button></form><div class="notice">Pairings are <strong>curated starting suggestions</strong>, not an objective fashion guarantee. Have your ministry coordinator review all combinations before publishing.</div></section><section class="panel"><div class="section-head"><div><h3 class="subhead">Approved outfits</h3><p class="caption">${validOutfits().length} usable · ${state.outfits.length} stored · Special-only items won't appear in normal rotation.</p></div></div><div class="outfits-scroll">${state.outfits.length?state.outfits.map(o=>`<div class="outfit-row"><div>${outfitPreview(o)}<div class="outfit-meta">${o.specialOnly?'<span class="tag special">Special rules only</span>':'<span class="tag">In normal rotation</span>'}${!isUsable(o)?'<span class="tag pending">Unavailable – tie not confirmed</span>':''}</div></div><div class="stack-sm"><button class="button small" data-action="toggleSpecial" data-id="${esc(o.id)}">${o.specialOnly?'Make regular':'Make special-only'}</button><button class="button small danger" data-action="removeOutfit" data-id="${esc(o.id)}">Remove</button></div></div>`).join(''):'<div class="empty"><strong>No approved outfits yet</strong>Add outfits using the form.</div>'}</div></section></div><div class="panel" style="margin-top:17px"><div class="setting-actions"><div><strong>Configuration &amp; reset</strong><p class="caption" style="margin:3px 0 0">Export a JSON backup before moving devices or resetting settings.</p></div><div class="hstack"><button class="button" data-action="exportJson">Download JSON</button><button class="button danger" data-action="reset">Reset to sample colours</button></div></div></div>`}
function optionsFor(cat,onlyConfirmed=false){return state.palette[cat].filter(x=>!onlyConfirmed||x.confirmed).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}
function ruleDescription(r){if(r.kind==='date')return dateFmt.format(parseISODate(r.date));return ({last:'Last',first:'First',second:'Second',third:'Third',fourth:'Fourth'}[r.kind]||r.kind)+' '+(WEEKDAYS[r.weekday]||'Sunday')+' of every month'}
function renderRules(){return `<section class="panel"><div class="section-head"><div><h2>Special uniform rules</h2><p>Reserve an approved outfit for a particular day. One-off date rules override recurring rules. Conflicting rules at the same priority block publishing.</p></div><button class="button" data-action="exportJson">Back up rules</button></div><div class="builder-grid"><div><h3 class="subhead">Add a rule</h3><form id="ruleForm" class="rule-form"><div class="field full"><label for="ruleName">Rule name</label><input type="text" name="name" id="ruleName" placeholder="e.g. All-black month end" maxlength="70" required></div><div class="field"><label for="ruleKind">When</label><select id="ruleKind" name="kind"><option value="last">Last of month</option><option value="first">First of month</option><option value="second">Second of month</option><option value="third">Third of month</option><option value="fourth">Fourth of month</option><option value="date">Specific date</option></select></div><div class="field" id="weekdayField"><label for="ruleWeekday">Service day</label><select name="weekday" id="ruleWeekday"><option value="0">Sunday</option><option value="5">Friday</option></select></div><div class="field" id="fixedDateField" style="display:none"><label for="ruleDate">Date (Sunday or Friday)</label><input id="ruleDate" type="date" name="date"></div><div class="field full"><label for="ruleOutfit">Approved outfit</label><select name="outfit" id="ruleOutfit" required>${validOutfits().map(o=>`<option value="${esc(o.id)}">${esc(outfitLabel(o))}</option>`).join('')}</select></div><button class="button primary full" type="submit" ${validOutfits().length===0?'disabled':''}>Add special rule</button></form><div class="notice"><strong>Example:</strong> Set “Last of month” + “Sunday” + your approved all-black outfit. Protocol has a starter rule; other ministries can configure their own.</div></div><div><h3 class="subhead">Active rules <span class="caption">(${state.rules.length})</span></h3><div class="rule-list">${state.rules.length?state.rules.slice().reverse().map(r=>{const o=state.outfits.find(x=>x.id===r.outfitId);return `<div class="rule-item"><div><strong>${esc(r.name)}</strong><p>${esc(ruleDescription(r))}</p><div class="outfit-meta">${outfitPreview(o)}${!isUsable(o)?'<span class="tag pending">Unavailable outfit</span>':''}</div></div><button class="button small danger" data-action="removeRule" data-id="${esc(r.id)}">Remove</button></div>`}).join(''):'<div class="empty"><strong>No special rules</strong>All services will use the normal outfit rotation.</div>'}</div></div></div><div class="sep"></div><h3 class="subhead">How the rules work</h3><div class="help-block"><div><strong>1 · Approved pairings only</strong><p>Every garment must exist in the palette and every complete look must be on the approved-outfits list.</p></div><div><strong>2 · Rules before rotation</strong><p>Fixed-date rules have highest priority. Recurring rules override automatically chosen looks for matching dates.</p></div><div><strong>3 · Balanced distribution</strong><p>All other dates prioritise a mix of suit colours and avoid repeats on consecutive services where possible.</p></div></div></section>`}
function outfitLabel(o){return ['suits','shirts','ties'].map((cat,i)=>item(cat,[o.suitId,o.shirtId,o.tieId][i])?.name||'Unknown').join(' / ')}
function changed(){save();render()}
async function handleClick(e){const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='printMember'){window.print();return}if(currentUser?.role!=='admin')return;
 if(b.dataset.tab){tab=b.dataset.tab;render();if(tab==='attendance')loadAttendanceList();return}
 const a=b.dataset.action;if(!a)return;
 if(a==='createMeeting'){await createAttendanceMeeting();return}
 if(a==='openMeeting'){await openAttendanceMeeting(Number(b.dataset.id));return}
 if(a==='closeMeeting'){if(!confirm('Close this QR check-in session?'))return;try{await api('/attendance/'+b.dataset.id+'/close',{method:'POST'});await loadAttendanceList();notify('Meeting closed.')}catch(e){notify(e.message,true)}return}
 if(a==='refreshAttendance'){await openAttendanceMeeting(Number(b.dataset.id));return}
 if(a==='addTeam'){const name=prompt('New ministry / department name:');if(!name?.trim())return;try{const team=await api('/teams',{method:'POST',body:payload({name:name.trim()})});workspace.teams[team.id]={name:team.name,slug:team.slug,version:team.version,data:team.config,published_at:null};workspace.active=String(team.id);state=team.config;tab='uniforms';render();notify('Ministry created.')}catch(e){notify(e.message,true)}return}
 if(a==='removeTeam'){const id=workspace.active;if(!confirm(`Permanently delete ${activeName()} and its published schedule? This cannot be undone.`))return;try{await api('/teams/'+id,{method:'DELETE'});delete workspace.teams[id];await selectTeam(Object.keys(workspace.teams)[0]);notify('Ministry removed.')}catch(e){notify(e.message,true)}return}
 if(a==='publish'){try{await (saveQueues[workspace.active]||Promise.resolve());if(syncErrors[workspace.active])throw Error('Unsaved changes: '+syncErrors[workspace.active]);const r=await api('/teams/'+workspace.active+'/publish',{method:'POST'});workspace.teams[workspace.active].published_at=r.published_at;render();notify('Published for '+r.count+' services. Members of this department can now view it.')}catch(e){notify(e.message,true)}return}
 if(a==='unpublish'){if(!confirm('Remove the published schedule from department member view?'))return;try{await api('/teams/'+workspace.active+'/unpublish',{method:'POST'});workspace.teams[workspace.active].published_at=null;render();notify('Published department schedule removed.')}catch(e){notify(e.message,true)}return}
 if(a==='publicLink'){copyText(location.origin+'/p/'+workspace.teams[workspace.active].slug);return}
 if(a==='branding'){document.getElementById('appearanceDialog').showModal();return}
 if(a==='exportWorkspace'){try{await Promise.all(Object.values(saveQueues));const all=await Promise.all(Object.keys(workspace.teams).map(id=>api('/teams/'+id+'/backup')));download('trfc-ministries-backup.json',JSON.stringify({exported_at:new Date().toISOString(),ministries:all,appearance:workspace.appearance},null,2),'application/json');notify('Workspace backup downloaded.')}catch(e){notify(e.message,true)}return}
 if(a==='copySchedule'){try{await (saveQueues[workspace.active]||Promise.resolve());if(syncErrors[workspace.active])throw Error('Unsaved changes: '+syncErrors[workspace.active]);const v=await api('/teams/'+workspace.active+'/preview');const rows=v.rows.map(r=>({date:r.date,month:r.date.slice(0,7),weekday:r.weekday,outfit:r.outfit?state.outfits.find(o=>o.id===r.outfit.id):null,rule:r.rule?{name:r.rule}:null}));copyText(scheduleAsText(rows))}catch(e){notify(e.message,true)}return}
 if(a==='exportCsv'){const id=workspace.active;await (saveQueues[id]||Promise.resolve());try{if(syncErrors[id])throw Error('Unsaved changes: '+syncErrors[id]);const res=await fetch('/api/teams/'+id+'/csv',{credentials:'same-origin'});if(!res.ok)throw Error('Could not export schedule.');const text=await res.text();download('trfc-'+workspace.teams[id].slug+'-schedule.csv',text,'text/csv;charset=utf-8')}catch(e){notify(e.message,true)}return}
 if(a==='print'){window.print();return}
 if(a==='exportJson'){download('ministry-'+workspace.active+'-settings.json',JSON.stringify(state,null,2),'application/json');return}
 if(a==='importJson'){document.getElementById('importFile').click();return}
 if(a==='reset'){if(confirm('Reset colours, approved combinations, special rules and schedule settings to defaults? Export JSON first if you need a backup.')){state=workspace.teams[workspace.active].slug==='protocol'?initialState():blankState();changed()}return}
 if(a==='confirmTie'||a==='unconfirmTie'){const t=item('ties',b.dataset.id);if(t){t.confirmed=a==='confirmTie';changed()}return}
 if(a==='removeColor'){const {kind,id}=b.dataset;const x=item(kind,id);if(!x)return;const prop={suits:'suitId',shirts:'shirtId',ties:'tieId'}[kind],affected=state.outfits.filter(o=>o[prop]===id),rCount=state.rules.filter(r=>affected.some(o=>o.id===r.outfitId)).length;
 if(confirm(`Remove ${x.name}? This also removes ${affected.length} approved outfit(s) and ${rCount} associated special rule(s).`)){const comboIds=new Set(affected.map(o=>o.id));state.palette[kind]=state.palette[kind].filter(c=>c.id!==id);state.outfits=state.outfits.filter(o=>!comboIds.has(o.id));state.rules=state.rules.filter(r=>!comboIds.has(r.outfitId));changed()}return}
 if(a==='removeOutfit'){const ruleCount=state.rules.filter(r=>r.outfitId===b.dataset.id).length;if(confirm(`Remove this approved combination${ruleCount?' and its '+ruleCount+' special rule(s)':''}?`)){state.outfits=state.outfits.filter(o=>o.id!==b.dataset.id);state.rules=state.rules.filter(r=>r.outfitId!==b.dataset.id);changed()}return}
 if(a==='toggleSpecial'){const o=state.outfits.find(x=>x.id===b.dataset.id);if(o){o.specialOnly=!o.specialOnly;changed()}return}
 if(a==='removeRule'){state.rules=state.rules.filter(r=>r.id!==b.dataset.id);changed();return}
}
document.addEventListener('click',handleClick);
document.addEventListener('change',e=>{if(currentUser?.role!=='admin')return;
 if(e.target.id==='teamSelect'){selectTeam(e.target.value).catch(err=>notify(err.message,true));return}
 if(e.target.id==='startMonth'){if(/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){state.settings.startMonth=e.target.value;changed()}return}
 if(e.target.id==='monthCount'){state.settings.months=Number(e.target.value);changed();return}
 if(e.target.id==='includeFridays'){state.settings.includeFridays=e.target.checked;changed();return}
 if(e.target.id==='ruleKind'){const fixed=e.target.value==='date';document.getElementById('fixedDateField').style.display=fixed?'flex':'none';document.getElementById('weekdayField').style.display=fixed?'none':'flex';return}
});
document.addEventListener('submit',e=>{
 const f=e.target;if(currentUser?.role!=='admin')return;if(!f.matches('.add-color-form,#outfitForm,#ruleForm,#labelsForm'))return;e.preventDefault();const data=new FormData(f);
 if(f.id==='labelsForm'){state.labels=Object.fromEntries(['suits','shirts','ties'].map(k=>[k,cleanText(data.get(k),40)||CATEGORIES[k]]));changed();return}
 if(f.matches('.add-color-form')){const kind=f.dataset.kind,name=cleanText(data.get('colorName'),50),hex=data.get('hex');if(!name)return;if(state.palette[kind].some(c=>c.name.toLowerCase()===name.toLowerCase())){alert('That colour already exists in this category.');return}state.palette[kind].push({id:uid(kind),name,hex,confirmed:true});changed();return}
 if(f.id==='outfitForm'){const suitId=data.get('suit'),shirtId=data.get('shirt'),tieId=data.get('tie');if(!item('suits',suitId)||!item('shirts',shirtId)||!item('ties',tieId)?.confirmed){alert('Please select existing colours, and confirm any printed tie first.');return}
 if(state.outfits.some(o=>o.suitId===suitId&&o.shirtId===shirtId&&o.tieId===tieId)){alert('This combination is already approved. You can change its rotation status in the list.');return}
 state.outfits.push({id:uid('combo'),suitId,shirtId,tieId,specialOnly:data.get('specialOnly')==='on'});changed();return}
 if(f.id==='ruleForm'){const kind=data.get('kind'),rawDate=data.get('date');let weekday=Number(data.get('weekday')),date='';if(kind==='date'){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(rawDate||'')){alert('Choose a date for this rule.');return}const d=parseISODate(rawDate);if(dateKey(d)!==rawDate||![0,5].includes(d.getUTCDay())){alert('Special dates must fall on a Sunday or Friday.');return}date=rawDate;weekday=d.getUTCDay();
 }
 const outfitId=data.get('outfit');if(!validOutfits().some(o=>o.id===outfitId)){alert('Choose a currently available approved outfit.');return}
 state.rules.push({id:uid('rule'),name:cleanText(data.get('name'),70),kind,weekday,date,outfitId});changed();return}
});
function csvValue(x){let v=String(x??'');if(/^[=+@\-]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'}
function exportCsv(){const rows=generate();const lines=[['Date','Day','Suit','Shirt','Tie','Type','Special rule'],...rows.map(r=>[r.date,WEEKDAYS[r.weekday],r.outfit?item('suits',r.outfit.suitId)?.name:'',r.outfit?item('shirts',r.outfit.shirtId)?.name:'',r.outfit?item('ties',r.outfit.tieId)?.name:'',r.rule?'Special':'Regular',r.rule?.name||''])];download('trfc-'+workspace.active+'-schedule-'+state.settings.startMonth+'.csv','\ufeff'+lines.map(r=>r.map(csvValue).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function download(name,body,type){const blob=new Blob([body],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function scheduleAsText(rows){let current='';return [activeName().toUpperCase()+' – UNIFORM SCHEDULE',''].concat(rows.map(r=>{let h='';if(r.month!==current){current=r.month;h='\n*'+monthFmt.format(parseISODate(r.month+'-01'))+'*\n'}return h+WEEKDAYS[r.weekday]+' '+dateFmt.format(parseISODate(r.date))+': '+(r.outfit?outfitLabel(r.outfit):'UNASSIGNED')+(r.rule?' ★ '+r.rule.name:'')}).flat()).join('\n')}
async function copyText(v){try{await navigator.clipboard.writeText(v);alert('Schedule copied. Paste it into WhatsApp or another message.')}catch(e){const t=document.createElement('textarea');t.value=v;t.style.position='fixed';t.style.left='-9999px';document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();if(ok)alert('Schedule copied.');else prompt('Copy your schedule:',v)}}
document.getElementById('importFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{const next=validateImport(JSON.parse(await f.text()));if(confirm('Replace all current uniform settings with this imported configuration?')){state=next;changed()}}catch(err){alert('Could not import: '+err.message)}e.target.value=''});
document.getElementById('appearanceForm').addEventListener('submit',async e=>{e.preventDefault();const next={...workspace.appearance,primary:document.getElementById('primaryColor').value,accent:document.getElementById('accentColor').value};const file=document.getElementById('logoFile').files[0];if(file){if(file.size>280000||!['image/png','image/jpeg','image/webp'].includes(file.type))return notify('Use a PNG/JPEG/WEBP under 280 KB.',true);next.logo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}try{workspace.appearance=await api('/branding',{method:'PUT',body:payload(next)});document.getElementById('appearanceDialog').close();render();notify('Branding updated for everyone.')}catch(err){notify(err.message,true)}});
document.getElementById('closeAppearance').onclick=()=>document.getElementById('appearanceDialog').close();
document.getElementById('clearEmblem').onclick=async()=>{workspace.appearance.logo='https://prophetdaviduche.net/img/Logo.png';try{workspace.appearance=await api('/branding',{method:'PUT',body:payload(workspace.appearance)});render();document.getElementById('appearanceDialog').close();notify('Official reference emblem restored.')}catch(e){notify(e.message,true)}};
document.getElementById('appearanceDialog').addEventListener('click',e=>{if(e.target.id==='appearanceDialog')e.target.close()});
document.getElementById('appearanceDialog').addEventListener('close',()=>{document.getElementById('primaryColor').value=workspace.appearance.primary;document.getElementById('accentColor').value=workspace.appearance.accent});
document.getElementById('primaryColor').value=workspace.appearance.primary;document.getElementById('accentColor').value=workspace.appearance.accent;
bootstrap();

// Authentication & member management
for(const f of ['loginForm','setupForm'])document.getElementById(f).addEventListener('submit',async e=>{e.preventDefault();document.getElementById('authError').textContent='';const d=new FormData(e.target);try{const loginData={email:d.get('email'),password:d.get('password')};if(f==='setupForm'){await api('/setup',{method:'POST',body:payload({...loginData,setup_key:d.get('setup_key')})})}const u=await api('/login',{method:'POST',body:payload(loginData)});await enter(u)}catch(err){document.getElementById('authError').textContent=err.message}});
document.getElementById('logoutButton').onclick=async()=>{try{await api('/logout',{method:'POST'});}catch{}location.reload()};
document.getElementById('accountButton').onclick=()=>{document.getElementById('passwordDialog').showModal()};
document.getElementById('passwordForm').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);if(d.get('password')!==d.get('verify'))return notify('Passwords do not match',true);try{await api('/users/'+currentUser.id+'/password',{method:'PUT',body:payload({current_password:d.get('current_password'),password:d.get('password')})});e.target.reset();document.getElementById('passwordDialog').close();notify('Password changed.')}catch(err){notify(err.message,true)}};
document.getElementById('usersButton').onclick=()=>{document.getElementById('userDialog').showModal();renderUsers()};
function syncUserRole(){const admin=document.getElementById('newUserRole').value==='admin';document.getElementById('userTeamChoices').querySelector('select')?.toggleAttribute('required',!admin);document.getElementById('userTeamChoices').classList.toggle('hide',admin)}
document.getElementById('newUserRole').addEventListener('change',syncUserRole);
async function renderUsers(){try{const users=await api('/users');document.getElementById('userList').innerHTML=users.map(u=>`<div class="member-item"><div><strong>${esc(u.email)}</strong><small>${u.role==='admin'?'Administrator':esc(workspace.teams[u.teams[0]]?.name||'No department')} · ${u.role==='admin'?'Full admin access':u.approved?'Approved member':'Pending approval'}</small></div><div class="hstack">${u.role!=='admin'?`<button class="button small" data-member-approve="${u.id}" type="button">${u.approved?'Suspend':'Approve'}</button><button class="button small" data-member-teams="${u.id}" type="button">Transfer</button><button class="button small danger" data-member-delete="${u.id}" type="button">Remove</button>`:''}<button class="button small" data-member-reset="${u.id}" type="button">Reset password</button></div></div>`).join('');document.getElementById('userTeamChoices').innerHTML=`<select name="teams" aria-label="Member department" required><option value="">Select a department</option>${Object.entries(workspace.teams).map(([id,t])=>`<option value="${id}">${esc(t.name)}</option>`).join('')}</select>`;syncUserRole();document.getElementById('userList').dataset.users=JSON.stringify(users)}catch(e){notify(e.message,true)}}
document.getElementById('addUserForm').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);try{const role=d.get('role');await api('/users',{method:'POST',body:payload({email:d.get('email'),password:d.get('password'),role,teams:role==='admin'?[]:[Number(d.get('teams'))]})});e.target.reset();await renderUsers();notify('Account created. Share the temporary password securely.')}catch(err){notify(err.message,true)}};
document.getElementById('userList').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const userId=Number(b.dataset.memberTeams||b.dataset.memberDelete||b.dataset.memberReset||b.dataset.memberApprove);const users=JSON.parse(document.getElementById('userList').dataset.users);const u=users.find(x=>x.id===userId);if(!u)return;
if(b.dataset.memberApprove){try{await api('/users/'+userId+'/approval',{method:'PUT',body:payload({approved:!u.approved})});await renderUsers();notify('Membership approval updated.')}catch(err){notify(err.message,true)}return}
if(b.dataset.memberDelete){if(!confirm('Remove '+u.email+' and their attendance records?'))return;try{await api('/users/'+userId,{method:'DELETE'});await renderUsers();notify('User removed.')}catch(err){notify(err.message,true)}return}
if(b.dataset.memberTeams){const options=Object.entries(workspace.teams).map(([id,t])=>`${id} = ${t.name}`).join('\n');const value=prompt('Administrator-only department transfer for '+u.email+'\n'+options,u.teams[0]||'');if(value===null)return;const teamId=Number(value);if(!Number.isInteger(teamId)||!workspace.teams[teamId])return notify('Choose a valid department ID.',true);try{await api('/users/'+userId+'/teams',{method:'PUT',body:payload({teams:[teamId]})});await renderUsers();notify('Member transferred.')}catch(err){notify(err.message,true)}return}
if(b.dataset.memberReset){if(userId===currentUser.id){document.getElementById('userDialog').close();document.getElementById('passwordDialog').showModal();return}const password=prompt('Set a new temporary password for '+u.email+' (at least 12 characters)');if(!password)return;try{await api('/users/'+userId+'/password',{method:'PUT',body:payload({password})});notify('Password reset. Share it securely.')}catch(err){notify(err.message,true)}}};

document.querySelectorAll('[data-close-dialog]').forEach(b=>b.onclick=()=>b.closest('dialog').close());

// Member view is deliberately read-only; the server never exposes draft configuration to members.
async function renderMemberDashboard(){
 const panel=document.getElementById('main');panel.innerHTML='<section class="panel"><h2>Loading your department…</h2></section>';
 try{
  const [schedule,attendance]=await Promise.all([api('/my-schedule'),api('/me/attendance')]);
  const parts=key=>schedule.labels?.[key]||({suits:'Main garment',shirts:'Second garment',ties:'Accessory'}[key]);
  const rows=schedule.rows||[];
  document.querySelector('.hero h1').textContent=schedule.name+' · Uniform schedule';
  document.querySelector('.hero p').textContent='Your department is locked to your account. Check your approved uniform schedule below, and scan the morning meeting QR to mark attendance.';
  document.getElementById('heroStats').innerHTML=`<div class="hero-stat"><strong>${rows.length}</strong><span>Scheduled services</span></div><div class="hero-stat"><strong>${attendance.length}</strong><span>My check-ins</span></div>`;
  panel.innerHTML=`${currentUser.approved?'':'<div class="notice warning">Your membership is awaiting administrator approval. You can view your department schedule, but QR check-in is disabled until approved.</div>'}<section class="panel"><div class="section-head"><div><span class="slabel">YOUR DEPARTMENT</span><h2>${esc(schedule.name)} · Published uniforms</h2><p>${schedule.published?'Read-only official schedule for your department.':'Your administrator has not published a schedule yet.'}</p></div><button class="button small" type="button" data-action="printMember">Print</button></div>${schedule.published?`<p class="table-hint">Swipe the table sideways to see every garment and note.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Published uniform schedule"><table class="data-table"><thead><tr><th>Date</th><th>Day</th><th>${esc(parts('suits'))}</th><th>${esc(parts('shirts'))}</th><th>${esc(parts('ties'))}</th><th>Note</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${r.weekday===5?'Friday':'Sunday'}</td>${['suits','shirts','ties'].map(k=>`<td>${esc(r.outfit?.parts?.[k]?.name||'Unassigned')}</td>`).join('')}<td>${esc(r.rule||'Standard')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">There are no published uniforms yet. Check back after your department administrator publishes.</div>'}</section><section class="panel"><div class="section-head"><div><h2>My attendance</h2><p>Before 08:30 = on time · 08:30–14:59 = late · from 15:00 = absent. Times are SAST.</p></div></div>${attendance.length?`<div class="table-scroll"><table class="data-table compact"><thead><tr><th>Meeting</th><th>Status</th></tr></thead><tbody>${attendance.map(a=>`<tr><td>${esc(a.date)}</td><td><span class="status-label status-${esc(a.status)}">${esc(a.status.replace('_',' '))}</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="caption">No QR check-ins recorded yet. Scan your department meeting QR when it is displayed.</p>'}</section>`;
 }catch(err){panel.innerHTML=`<section class="panel"><h2>Unable to load schedule</h2><p>${esc(err.message)}</p></section>`}
}

let attendanceMeetingId=null;
function renderAttendance(){return `<section class="panel"><div class="section-head"><div><span class="slabel">DEPARTMENT ATTENDANCE</span><h2>QR morning roll call</h2><p>On-time before 08:30 · Late 08:30–14:59 · Absent from 15:00 (Africa/Johannesburg). Only approved members can check in.</p></div></div><div class="controls"><div class="field"><label for="meetingDate">Meeting date</label><input id="meetingDate" type="date" value="${new Intl.DateTimeFormat('sv-SE',{timeZone:'Africa/Johannesburg'}).format(new Date())}"></div><button class="button primary" data-action="createMeeting">Open QR attendance</button></div><div id="attendanceBody"><p class="caption">Loading meetings…</p></div></section>`}
async function loadAttendanceList(){const body=document.getElementById('attendanceBody');if(!body)return;try{const meetings=await api('/teams/'+workspace.active+'/attendance');body.innerHTML=`<h3>Recent meetings</h3>${meetings.length?`<div class="meeting-list">${meetings.map(m=>`<div class="member-item"><div><strong>${esc(m.date)}</strong><small>${m.checkins} recorded check-ins · ${m.active?'Open':'Closed'}</small></div><button class="button small" data-action="openMeeting" data-id="${m.id}">View roll call</button></div>`).join('')}</div>`:'<div class="notice">No attendance meetings have been created for this department.</div>'}<div id="attendanceReport"></div>`;if(attendanceMeetingId&&meetings.some(m=>m.id===attendanceMeetingId))await openAttendanceMeeting(attendanceMeetingId)}catch(e){body.textContent=e.message}}
async function createAttendanceMeeting(){try{const date=document.getElementById('meetingDate').value;const m=await api('/teams/'+workspace.active+'/attendance',{method:'POST',body:payload({service_date:date})});attendanceMeetingId=m.id;await loadAttendanceList();notify('Attendance QR created for '+m.date)}catch(e){notify(e.message,true)}}
async function openAttendanceMeeting(id){try{const meeting=await api('/attendance/'+id);attendanceMeetingId=id;const area=document.getElementById('attendanceReport');if(!area)return;const stats={on_time:0,late:0,absent:0,pending:0};meeting.roster.forEach(r=>stats[r.status]++);area.innerHTML=`<div class="sep"></div><div class="section-head"><div><h2>${esc(meeting.name)} — ${esc(meeting.date)}</h2><p>${stats.on_time} on time · ${stats.late} late · ${stats.absent} absent · ${stats.pending} pending</p></div><div class="hstack"><a class="button small" href="/api/attendance/${id}/csv" download>Export roll call</a><button class="button small" data-action="refreshAttendance" data-id="${id}">Refresh</button>${meeting.active?`<button class="button small danger" data-action="closeMeeting" data-id="${id}">Close QR</button>`:''}</div></div>${meeting.active?`<div class="qr-panel"><img src="${meeting.qr_image}" alt="Scan to check in" width="240" height="240"><div><strong>Scan at the morning meeting</strong><p>Members sign in on their own phones to record attendance. This QR is valid only for this department and date.</p><button class="button small" type="button" id="copyCheckinLink">Copy check-in link</button></div></div>`:''}<div class="table-scroll"><table class="data-table"><thead><tr><th>Member email</th><th>Approval</th><th>Attendance</th><th>Checked in (UTC)</th></tr></thead><tbody>${meeting.roster.map(r=>`<tr><td>${esc(r.email)}</td><td>${r.approved?'Approved':'Pending'}</td><td><span class="status-label status-${esc(r.status)}">${esc(r.status.replace('_',' '))}</span></td><td>${esc(r.checked_in_at||'—')}</td></tr>`).join('')}</tbody></table></div>`;const copy=document.getElementById('copyCheckinLink');if(copy)copy.onclick=()=>copyText(meeting.qr_url)}catch(e){notify(e.message,true)}}

async function loadDepartments(){try{const departments=await api('/departments');document.getElementById('registerDepartment').innerHTML='<option value="">Choose your department</option>'+departments.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}catch(e){notify(e.message,true)}}
document.getElementById('showRegister').onclick=()=>{document.getElementById('registerForm').classList.remove('hide');document.getElementById('loginForm').classList.add('hide');document.getElementById('authModeTitle').textContent='Create your account';loadDepartments()};
document.getElementById('showLogin').onclick=()=>{document.getElementById('registerForm').classList.add('hide');document.getElementById('loginForm').classList.remove('hide');document.getElementById('authModeTitle').textContent='Welcome back'};
document.getElementById('registerForm').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);try{await api('/register',{method:'POST',body:payload({email:data.get('email'),password:data.get('password'),department_id:Number(data.get('department_id'))})});const u=await api('/login',{method:'POST',body:payload({email:data.get('email'),password:data.get('password')})});await enter(u);notify('Account created. An administrator must approve your attendance eligibility.')}catch(err){document.getElementById('authError').textContent=err.message}};
